pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        // 1. Admissible domain: amount not zero to have a meaningful deposit, actor not the zero address
        vm.assume(amount > 0);
        vm.assume(actor != address(0));

        // 2. Set up and drive through addToBalance
        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();

        // 3. Assert invariant: sum of all stored balances == contract ETH balance
        // We compute sum of balances over all actors we know. Since mapping keys are not enumerable,
        // we restrict to the known actors: `actor` and `address(0)`.
        // The correct contract stores for `actor`; the mutant for `address(0)`.
        // Both contracts store 0 for the other key initially.
        uint256 sum = c.getBalance(actor) + c.getBalance(address(0));
        assertTrue(sum == address(c).balance);
    }
}

